def no_order(equation):
    if not equation:
        return None

    # Split the equation into tokens
    tokens = equation.split()

    # Initialize the result with the first number
    result = int(tokens[0])

    # Iterate through the tokens starting from the second element
    for i in range(1, len(tokens), 2):
        operator = tokens[i]
        next_number = int(tokens[i + 1])

        # Handle each operator
        if operator == '+':
            result += next_number
        elif operator == '-':
            result -= next_number
        elif operator == '*':
            result *= next_number
        elif operator == '/':
            if next_number == 0:
                return None
            result //= next_number
        elif operator == '^':
            result **= next_number
        elif operator == '%':
            if next_number == 0:
                return None
            result %= next_number

    return result

def hamster_me(code, message):
    # Create a mapping of each letter to its position in the code
    code_map = {char: idx + 1 for idx, char in enumerate(code)}

    # Initialize the result string and a position counter
    result = []
    position = 1

    # Iterate through each character in the message
    for char in message:
        if char in code_map:
            # Append the position of the character as a string to the result
            result.append(str(code_map[char]))
        else:
            # Find the next available position in the code map
            while position > len(code_map):
                position += 1
            # Append the position to the result and update the code map
            result.append(str(position))
            code_map[char] = position
            position += 1

    # Join the result list into a string and return it
    return ''.join(result)

