def repeat_sequence_len(a0):
    def F(N):
        return sum(int(digit) ** 2 for digit in str(N))

    seen = set()
    sequence = [a0]

    while True:
        next_number = F(sequence[-1])
        if next_number in seen:
            return len(sequence) - sequence.index(next_number)
        seen.add(next_number)
        sequence.append(next_number)

