def create_anagram(s, t):
    # Step 1: Count the frequency of each character in string s
    s_count = {}
    for char in s:
        if char in s_count:
            s_count[char] += 1
        else:
            s_count[char] = 1

    # Step 2: Count the frequency of each character in string t
    t_count = {}
    for char in t:
        if char in t_count:
            t_count[char] += 1
        else:
            t_count[char] = 1

    # Step 3: Calculate the number of replacements needed
    replacements = 0
    for char in s_count:
        if char in t_count:
            replacements += abs(s_count[char] - t_count[char])
        else:
            replacements += s_count[char]

    # Step 4: Return the total number of replacements
    return replacements
